const C=InteriorCore, $=(s,root=document)=>root.querySelector(s), esc=C.escape;
let db={projects:[],items:[],clients:[],history:[],notifications:[],assignments:[],members:[],companies:[]}, prefs={lang:'ko',logo:''}, storageWarning=false;
let lang=C.language(prefs.lang),route=C.parseRoute(location.hash),filter='all',query='',month=new Date(),toastTimer;
const t=key=>COPY[key]?.[lang==='en'?1:0]??key;
const paths={plus:'M12 5v14M5 12h14',arrow:'M5 12h14M13 6l6 6-6 6',folder:'M3 7V5h6l2 2h10v13H3z',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zM10 21h4',settings:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M9 15v6',image:'M3 3h18v18H3zM3 17l6-6 4 4 3-3 5 5M8 7h.01',file:'M6 2h8l4 4v16H6zM14 2v5h5M9 12h6M9 16h6',close:'M6 6l12 12M18 6L6 18',grid:'M3 3h18v18H3zM3 12h18M12 3v18',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',left:'M15 5l-7 7 7 7',right:'M9 5l7 7-7 7'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const id=()=>globalThis.crypto?.randomUUID?.()||('i'+Date.now().toString(36)+Math.random().toString(36).slice(2));
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const formatDate=value=>value?new Intl.DateTimeFormat(lang==='ko'?'ko-KR':'en-US',{year:'numeric',month:'short',day:'numeric',timeZone:'Asia/Seoul'}).format(new Date(value.length===10?value+'T12:00:00+09:00':value)):t('notEntered');
const href=(tab,p=route?.project,item='',role=route?.role||'pm')=>`#/${role}/project/${p}/${tab}${item?'/'+item:''}`;
const badge=(key,positive=false)=>`<span class="badge ${positive?'positive':''}"><span class="dot"></span>${esc(t(key))}</span>`;
const button=(label,action,primary=false,extra='')=>`<button class="button ${primary?'primary':''}" data-action="${action}" ${extra}>${primary?icon('plus'):''}${esc(t(label))}</button>`;
const empty=(title='empty',body='emptyText',action='',compact=false)=>`<div class="empty ${compact?'compact':''}"><div class="empty-symbol">${icon('folder')}</div><h2>${esc(t(title))}</h2><p>${esc(t(body))}</p>${action}</div>`;
const heading=(title,sub='',actions='',eyebrow='')=>`<div class="page-heading"><div>${eyebrow?`<span class="eyebrow">${esc(eyebrow)}</span>`:''}<h1 tabindex="-1" id="page-title">${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div><div class="actions">${actions}</div></div>`;
const note=key=>`<div class="notice">${esc(t(key))}</div>`;
const brand=()=>prefs.logo?`<img src="${prefs.logo}" alt="${esc(t('logoAlt'))}">`:`<span class="brand-mark">${icon('grid')}</span><span>${esc(t('brand'))}</span>`;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;toastTimer=setTimeout(()=>$('#toast').textContent='',5000);}
function currentProject(){return db.projects.find(p=>p.id===route?.project&&!p.archived&&(route.role!=='customer'||p.public));}
function items(type,p=route?.project){return db.items.filter(i=>i.project===p&&i.type===type&&!i.archived&&(route.role!=='customer'||i.public));}
function navigate(hash){if(location.hash===hash)render();else location.hash=hash;}
function homeRoute(role){return `#/${role}/${role==='field'?'photos':'projects'}`;}
/* 02 — Persistent navigation shell and fail-closed routes */
function render(focus=false){
 if(!session?.user)return renderAuth();
 route=C.parseRoute(location.hash);if(!route||route.role!==session.user.role){location.hash=homeRoute(session.user.role);route=C.parseRoute(location.hash);}
 if(route.role==='field'){route.tab='photos';if(route.project)fieldProject=route.project;route.project=fieldProject;}const role=route.role;
 document.documentElement.lang=lang;document.title=t('brand');$('#skip').textContent=t('skip');
 const nav=role==='pm'?['projects','customers','calendar','history']:role==='customer'?['projects']:['photos'];
 const p=currentProject();let crumbs=`<a href="${homeRoute(role)}">${esc(t(role==='customer'?'myProjects':role==='field'?'photos':'projects'))}</a>`;
 if(p)crumbs+=`<span aria-hidden="true">/</span><a href="${href('overview')}">${esc(p.title)}</a><span aria-hidden="true">/</span><span>${esc(t(route.tab))}</span>`;
 $('#app').innerHTML=`
 <header class="site-header"><div class="header-inner"><a class="brand" href="${homeRoute(role)}" aria-label="${esc(t('brand'))}">${brand()}</a>
 <nav class="global-nav" aria-label="${esc(t('projects'))}">${nav.map(n=>`<a class="nav-link" href="#/${role}/${n}" ${route?.page===n||(n==='projects'&&route?.page==='project')?'aria-current="page"':''}>${esc(t(role==='customer'&&n==='projects'?'myProjects':n))}</a>`).join('')}</nav>
 <div class="header-tools"><a class="icon-button" href="#/${role}/notifications" aria-label="${esc(t('notifications'))}">${icon('bell')}</a><a class="icon-button" href="#/${role}/preferences" aria-label="${esc(t('preferences'))}">${icon('image')}</a>${role==='pm'?`<a class="icon-button company-settings" href="#/pm/settings" aria-label="${esc(t('settings'))}">${icon('settings')}</a>`:''}<div class="language" aria-label="${esc(t('languageTitle'))}"><button data-lang="ko" lang="ko" aria-label="한국어" aria-pressed="${lang==='ko'}">KO</button><button data-lang="en" lang="en" aria-label="English" aria-pressed="${lang==='en'}">EN</button></div></div></div></header>
 <main class="workspace" id="main" tabindex="-1"><div class="utility-row"><nav class="breadcrumbs" aria-label="${esc(t('project'))}">${crumbs}</nav><div class="role-select"><span class="account-dot" aria-hidden="true"></span>${esc(session.user.name)}<span class="account-role">${esc(t(role))}</span></div></div>${view()}</main>
 <footer class="site-footer"><button class="button subtle" id="logout">${esc(t('logout'))}</button><button class="button subtle" id="password-change">${esc(t('passwordChange'))}</button><button class="button subtle" id="refresh-state">${esc(t('refresh'))}</button><span>${esc(t('footer'))}</span>${role==='pm'?`<a href="#/pm/settings">${esc(t('settings'))}</a>`:''}<a href="#/${role}/preferences">${esc(t('preferences'))}</a><button class="button subtle" data-action="help">${esc(t('localHelp'))}</button></footer>`;
 bind();enhance();bindServer();if(focus)$('#page-title')?.focus({preventScroll:true});if(storageWarning){toast(t('storageError'));storageWarning=false;}
}
function view(){
 if(!route)return unavailable();
 if(route.page==='preferences')return preferencesView();
 if(route.page==='settings')return companyView();
 if(route.page==='notifications')return notificationsView();
 if(route.page==='customers')return clientsView();
 if(route.role==='field')return fieldView();
 if(route.page==='history')return historyView();
 if(route.page==='calendar')return heading(t('calendar'))+calendarView(db.items.filter(i=>i.type==='schedule'),true);
 if(route.page==='projects')return projectsView();
 if(route.page==='project')return projectView();return unavailable();
}
function unavailable(){return heading(t('noAccess'))+`<div class="panel">${empty('noAccess','noAccessText',`<a class="button" href="${homeRoute(route?.role||'pm')}">${esc(t('back'))}</a>`)}</div>`;}
function projectsView(){
 const all=db.projects.filter(p=>!p.archived&&(route.role!=='customer'||p.public));
 const pm=route.role==='pm';
 const summary=pm?`<div class="stats">${[['totalProjects',all.length],['activeProjects',all.filter(p=>p.status==='active').length],['openRequests',db.items.filter(i=>i.type==='requests'&&i.status!=='resolved').length],['upcoming',db.items.filter(i=>i.type==='schedule'&&i.date>=today()).length]].map(([label,n],i)=>`<div class="stat"><div class="stat-top"><span>${esc(t(label))}</span><span class="mono">0${i+1}</span></div><strong>${String(n).padStart(2,'0')}</strong><small>${esc(t('localRecords'))}</small></div>`).join('')}</div>`:'';
 return heading(t(pm?'projectHeading':'myProjects'),t(pm?'projectSub':'noPublicProjectsHint'),pm?button('newProject','new-project',true):'','PROJECT WORKSPACE / 01')+summary+
 `<div class="toolbar"><div class="segmented" aria-label="${esc(t('status'))}">${['all','active','planned','completed'].map(k=>`<button data-filter="${k}" aria-pressed="${filter===k}">${esc(t(k))}</button>`).join('')}</div><label class="search">${icon('search')}<span class="sr-only">${esc(t('search'))}</span><input id="search" value="${esc(query)}" placeholder="${esc(t('searchPlaceholder'))}" type="search"></label></div>
 <div class="content-grid"><section class="panel" aria-labelledby="projects-title"><div class="panel-head"><h2 class="panel-title" id="projects-title">${esc(t('projectList'))}</h2><span class="mono" id="result-count">${all.length}</span></div><div id="project-results">${projectResults(all)}</div></section><aside><div class="panel"><div class="panel-head"><h2 class="panel-title">${esc(t('startGuide'))}</h2>${icon('arrow')}</div><div class="panel-body">${[1,2,3].map(n=>`<div class="guide-step"><span>0${n}</span><div><h3>${esc(t('step'+n))}</h3><p>${esc(t('step'+n+'Text'))}</p></div></div>`).join('')}</div></div>${note('noSample')}<a class="text-link" href="#/${route.role}/preferences">${esc(t('logoUpload'))}${icon('arrow')}</a></aside></div>`;
}
function projectResults(all){const list=all.filter(p=>(filter==='all'||p.status===filter)&&(p.title+' '+p.site).toLowerCase().includes(query.toLowerCase()));
 if(!list.length)return empty(all.length?'noMatches':route.role==='pm'?'emptyProjects':'noPublicProjects',all.length?'noMatchesText':route.role==='pm'?'emptyProjectText':'noPublicProjectsHint',route.role==='pm'&&!all.length?button('newProject','new-project',true):'');
 const cards=rows=>rows.map(p=>`<a class="project-card" href="${href('overview',p.id)}"><div class="project-card-head"><h2>${esc(p.title)}</h2>${icon('arrow')}</div><div class="project-meta">${badge(p.status,p.status==='active')}<span>${esc(p.site||t('notEntered'))}</span><span>${esc(formatDate(p.start))} — ${esc(formatDate(p.end))}</span></div></a>`).join('');
 if(route.role!=='customer')return cards(list);
 const groups=new Map();for(const p of list){if(!groups.has(p.company))groups.set(p.company,[]);groups.get(p.company).push(p);}
 return [...groups.values()].map(rows=>`<section class="company-project-group"><div class="panel-head"><h3>${esc(rows[0].companyTitle||t('notEntered'))}</h3><span class="mono">${rows.length}</span></div>${cards(rows)}</section>`).join('');
}
function projectView(){const p=currentProject();if(!p)return unavailable();
 const tabs=route.role==='pm'?C.tabs:C.tabs.filter(k=>k!=='settings');
 const shell=projectSwitcher(p)+heading(p.title,`${p.site||t('notEntered')}  /  ${formatDate(p.start)} — ${formatDate(p.end)}`,badge(p.status,p.status==='active'),'PROJECT / '+t(route.tab))+
 `<nav class="project-tabs" aria-label="${esc(t('project'))}">${tabs.map(k=>`<a class="${k==='settings'?'settings-tab':''}" href="${href(k)}" ${route.tab===k?'aria-current="page"':''}>${esc(t(k==='overview'&&route.role==='customer'?'home':k==='settings'?'projectSettings':k))}</a>`).join('')}</nav>`;
 if(route.item){const item=items(route.tab).find(i=>i.id===route.item);return item?shell+detailView(item):unavailable();}
 if(route.tab==='overview')return shell+overviewView(p);
 if(route.tab==='settings')return shell+`<section class="panel"><div class="panel-head"><h2>${esc(t('projectSettings'))}</h2>${button('edit','edit-project')}</div><div class="panel-body">${details([['title',p.title],['site',p.site],['status',t(p.status)],['visibility',t(p.public?'public':'private')]])}</div></section>`+participantsView(p);
 const canAdd=route.role==='pm'||route.tab==='requests'||(route.role==='field'&&route.tab==='photos');
 const bar=workFilters()+`<div class="toolbar"><h2>${esc(t(route.tab))} <span class="muted mono">${items(route.tab).length}</span></h2>${canAdd?button(route.tab==='requests'?'newRequest':['designs','photos','estimates'].includes(route.tab)?'upload':'add','add-item',true):''}</div>`;
 if(route.tab==='schedule')return shell+bar+calendarView(filteredItems(items('schedule')));
 const list=filteredItems(items(route.tab));if(!list.length)return shell+bar+`<div class="panel">${empty('empty',route.role==='pm'?'emptyText':'readOnlyEmpty')}</div>`;
 if(route.tab==='photos')return shell+bar+`<div class="panel photo-grid">${list.map(i=>`<a class="photo-card" href="${href('photos',p.id,i.id)}"><img src="${safeImage(i.data)}" alt="${esc(i.description||i.title)}"><h3>${esc(i.title)}</h3><p>${esc(i.phase)} · ${esc(formatDate(i.date))}</p>${badge(i.public?'public':'private')}</a>`).join('')}</div>`;
 return shell+bar+`<div class="panel table-scroll"><table><thead><tr><th scope="col">${esc(t('title'))}</th><th scope="col">${esc(t(route.tab==='materials'?'space':route.tab==='requests'?'status':'fileType'))}</th><th scope="col">${esc(t('visibility'))}</th><th scope="col">${esc(t('created'))}</th></tr></thead><tbody>${list.map(i=>`<tr><td><a href="${href(i.type,p.id,i.id)}">${esc(i.title)}</a></td><td>${esc(i.type==='materials'?i.space:i.type==='requests'?t(i.status):i.fileName?.split('.').pop().toUpperCase())}</td><td>${badge(i.public?'public':'private')}</td><td>${esc(formatDate(i.created))}</td></tr>`).join('')}</tbody></table></div>`;
}
function details(pairs){return `<dl class="details">${pairs.map(([key,value])=>`<dt>${esc(t(key))}</dt><dd>${esc(value||t('notEntered'))}</dd>`).join('')}</dl>`;}
function baseOverviewView(p){const next=items('schedule').filter(i=>i.date>=today()).sort((a,b)=>a.date.localeCompare(b.date))[0];const recent=db.history.filter(h=>h.project===p.id&&(route.role==='pm'||db.items.some(i=>i.id===h.idRef&&i.public))).slice(0,4);
 return `<div class="content-grid"><div><section class="panel"><div class="panel-head"><h2>${esc(t('overview'))}</h2>${badge(p.public?'public':'private')}</div><div class="panel-body">${details([['site',p.site],['currentPhase',p.phase],['start',formatDate(p.start)],['end',formatDate(p.end)]])}</div></section><section class="panel"><div class="panel-head"><h2>${esc(t('recentUpdates'))}</h2></div>${recent.length?`<div class="panel-body timeline">${recent.map(h=>`<div class="timeline-row"><span class="muted small">${esc(formatDate(h.at))}</span><a href="${href(h.type,p.id,h.type==='overview'?'':h.idRef)}">${esc(h.title)} <span class="muted small">· ${esc(t(h.key))}</span></a></div>`).join('')}</div>`:empty('noUpdates','localRecords','',true)}</section></div><aside><section class="panel"><div class="panel-head"><h2>${esc(t('nextSchedule'))}</h2>${icon('clock')}</div>${next?`<div class="panel-body"><span class="eyebrow">${esc(formatDate(next.date))}</span><h2>${esc(next.title)}</h2><p class="panel-description">${esc(next.description)}</p><a class="text-link" href="${href('schedule',p.id,next.id)}">${esc(t('detail'))}${icon('arrow')}</a></div>`:empty('noSchedule','emptyText','',true)}</section>${note('previewNote')}</aside></div>`;
}
function safeImage(value){return typeof value==='string'&&(/^[\/]api[\/]files[\/][a-zA-Z0-9_-]+$/.test(value)||/^data:image\/(png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(value))?value:'';}
function baseDetailView(item){const pm=route.role==='pm';const top=`<div class="toolbar"><a class="text-link" href="${href(item.type)}">${icon('left')}${esc(t('back'))}</a><div class="actions">${badge(item.public?'public':'private')}${pm?button('edit','edit-item')+`<button class="button" data-archive="${esc(item.id)}">${esc(t('archive'))}</button>`:''}</div></div>`;
 let body='';
 if(item.type==='designs'||item.type==='estimates'){
 const pdf=/\.pdf$/i.test(item.fileName);body=`<section class="panel"><div class="panel-head"><h2>${esc(item.title)}</h2></div><div class="panel-body">${details([['fileName',item.fileName],['created',formatDate(item.created)],...(item.type==='estimates'?[['version',item.versionLabel],['publishedAt',item.publishedAt?new Date(item.publishedAt).toLocaleString(lang==='ko'?'ko-KR':'en-US'):t('private')]]:[])])}<p class="description panel-description">${esc(item.description)}</p><div class="actions" style="margin-top:20px"><a class="button" href="${esc(safeFile(item.data))}" download="${esc(item.fileName)}">${icon('file')}${esc(t('download'))}</a>${pdf?`<a class="button" href="${esc(safeFile(item.data))}?preview=1" target="_blank" rel="noopener">${esc(t('pdfPreview'))}</a>`:''}</div>${!pdf?note('noPreview'):''}</div></section>`;
 if(item.type==='designs')body+=confirmationView(item)+compareView(item);
 }else if(item.type==='materials')body=`<section class="panel"><div class="panel-head"><h2>${esc(item.title)}</h2>${badge(item.confirmation?'confirmed':'pending')}</div><div class="panel-body">${item.materialImage?`<img class="material-detail-image" src="${safeImage(item.materialImage)}" alt="${esc(item.title)}">`:''}${details([['category',item.category],['space',item.space],['spec',item.spec],['quantity',item.quantity],['unitPrice',item.price]])}${confirmationView(item)}</div></section>`;
 else if(item.type==='requests')body=`<div class="content-grid"><section class="panel"><div class="panel-head"><h2>${esc(item.title)}</h2>${badge(item.status)}</div><div class="panel-body"><span class="eyebrow">${esc(t('original'))}</span><p class="description">${esc(item.description)}</p><h3 style="margin-top:28px">${esc(t('corrections'))}</h3>${(item.corrections||[]).map(c=>`<div class="notice"><small>${esc(formatDate(c.at))}</small><p class="description">${esc(c.text)}</p></div>`).join('')}<div style="margin-top:20px">${button('correction','correct-request')}</div></div></section><aside class="panel"><div class="panel-head"><h2>${esc(t('answer'))}</h2></div><div class="panel-body"><p class="description">${esc(item.answer||t('noAnswer'))}</p>${pm?`<div style="margin-top:24px">${button('reply','reply-request')}</div>`:''}</div></aside></div>`;
 else if(item.type==='photos')body=`<section class="panel"><img class="photo-detail" src="${safeImage(item.data)}" alt="${esc(item.description||item.title)}"><div class="panel-body"><h2>${esc(item.title)}</h2>${details([['phase',item.phase],['shotDate',formatDate(item.date)],['uploader',item.uploaderName||item.uploader||session.user.name],['created',formatDate(item.created)]])}<p class="description panel-description">${esc(item.description)}</p><a class="text-link" href="${safeImage(item.data)}" download="${esc(item.fileName)}">${esc(t('download'))}</a></div></section>`;
 else if(item.type==='schedule')body=`<section class="panel"><div class="panel-head"><h2>${esc(item.title)}</h2><span class="mono">ASIA / SEOUL</span></div><div class="panel-body">${details([['startDate',formatDate(item.date)],['startTime',item.time],['endDate',formatDate(item.endDate||item.date)],['endTime',item.endTime],['project',currentProject().title]])}<p class="description panel-description">${esc(item.description)}</p><p class="notice">${esc(t('seoulTime'))}</p></div></section>`;
 return top+body;
}
/* 03 — Comparison and Sunday-start calendar */
function compareView(item){return `<section class="panel"><div class="panel-head"><h2>${esc(t('compare'))}</h2>${route.role==='pm'?button('addPreview','add-preview'):''}</div><div class="panel-body"><p class="small muted" style="margin-bottom:20px">${esc(t('compareHint'))}</p><div class="form-grid" style="margin-bottom:20px">${['a','b'].map(side=>`<label class="field">${esc(t(side==='a'?'previewA':'previewB'))}<select id="image-${side}"></select></label>`).join('')}</div><div class="compare-stage unavailable" id="compare-stage"><img class="image-b" id="compare-b" alt="${esc(t('imageBAlt'))}"><div class="compare-a-layer"><img class="image-a" id="compare-a" alt="${esc(t('imageAAlt'))}"></div><div class="compare-line"></div><div class="compare-tags"><span>A</span><span>B</span></div><div class="compare-message" id="compare-message">${esc(t('compareEmpty'))}</div><input type="range" min="0" max="100" step="1" value="50" id="compare-range" aria-label="${esc(t('compareRange'))}" disabled></div><div class="compare-footer"><span>${esc(t('compareKey'))}</span><output id="compare-output" for="compare-range">A 50% / B 50%</output></div></div></section>`;}
function setupCompare(){if(!$('#compare-range'))return;const all=items('designs').flatMap(i=>(i.previews||[]).map(p=>({...p,drawTitle:i.title})));let generation=0;
 for(const side of ['a','b']){$('#image-'+side).innerHTML=`<option value="">${esc(t('selectImage'))}</option>`+all.map(i=>`<option value="${esc(i.id)}">${esc(i.drawTitle+' / '+i.title)}</option>`).join('');$('#image-'+side).addEventListener('change',refresh);}
 if(all.length>=2){$('#image-a').value=all[0].id;$('#image-b').value=all[1].id;refresh();}
 async function refresh(){const g=++generation;const a=all.find(i=>i.id===$('#image-a').value),b=all.find(i=>i.id===$('#image-b').value);const stage=$('#compare-stage'),range=$('#compare-range');stage.classList.add('unavailable');range.disabled=true;$('#compare-message').hidden=false;
 if(!a||!b||a.id===b.id){$('#compare-message').textContent=t(a&&b?'compareSame':'compareEmpty');return;}
 try{await Promise.all([decodeComparisonImage(a.data),decodeComparisonImage(b.data)]);if(g!==generation||!stage.isConnected)return;$('#compare-a').src=safeImage(a.data);$('#compare-b').src=safeImage(b.data);stage.classList.remove('unavailable');$('#compare-message').hidden=true;range.disabled=false;range.value=50;sync();}catch(error){if(g===generation&&stage.isConnected)$('#compare-message').textContent=t(error.message==='compareDenied'?'compareDenied':'invalidImage');}}
 function sync(){const n=C.split($('#compare-range').value);$('#compare-stage').style.setProperty('--split',n+'%');$('#compare-output').textContent=`A ${n}% / B ${100-n}%`;$('#compare-range').setAttribute('aria-valuetext',`A ${n}%, B ${100-n}%`);}
 $('#compare-range').addEventListener('input',sync);
}
function calendarView(events,global=false){const y=month.getFullYear(),m=month.getMonth();const monthLabel=new Intl.DateTimeFormat(lang==='ko'?'ko-KR':'en-US',{year:'numeric',month:'long'}).format(month);const sorted=[...events].sort((a,b)=>(a.date+(a.time||'')).localeCompare(b.date+(b.time||'')));return `<section class="panel"><div class="calendar-top"><h2>${esc(monthLabel)}</h2><div class="actions"><button class="icon-button" data-month="-1" aria-label="${esc(t('prevMonth'))}">${icon('left')}</button><button class="icon-button" data-month="1" aria-label="${esc(t('nextMonth'))}">${icon('right')}</button></div></div><div class="calendar" role="group" aria-label="${esc(t('monthly'))}">${t('weekdays').split(',').map(d=>`<div class="weekday">${d}</div>`).join('')}${C.monthCells(y,m).map(d=>{const date=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;return `<div class="calendar-day ${d&&date===today()?'today':''}">${d?`<span>${d}</span>`:''}${d?events.filter(i=>i.date===date).map(i=>`<a class="calendar-event" href="${href('schedule',i.project,i.id)}">${esc(i.title)}</a>`).join(''):''}</div>`;}).join('')}</div></section><section class="panel"><div class="panel-head"><h2>${esc(t('timeline'))}</h2></div>${sorted.length?`<div class="panel-body timeline">${sorted.map(i=>`<a class="timeline-row" href="${href('schedule',i.project,i.id)}"><span class="muted">${esc(scheduleRange(i))}</span><span>${esc(i.title)}${global?` <small class="muted">/ ${esc(db.projects.find(p=>p.id===i.project)?.title)}</small>`:''}</span></a>`).join('')}</div>`:empty('noSchedule','emptyText','',true)}</section>`;}
function baseHistoryView(){return heading(t('history'),t('localRecords'))+`<div class="panel">${db.history.length?`<div class="table-scroll"><table><thead><tr><th>${esc(t('date'))}</th><th>${esc(t('record'))}</th><th>${esc(t('changes'))}</th></tr></thead><tbody>${db.history.map(h=>`<tr><td>${esc(formatDate(h.at))}</td><td><a href="${href(h.type,h.project,h.type==='overview'?'':h.idRef,'pm')}">${esc(h.title)}</a></td><td>${esc(t(h.key))}</td></tr>`).join('')}</tbody></table></div>`:empty('noUpdates','localRecords')}</div>`;}
function preferencesView(){return heading(t('logoTitle'),t('logoSub'),'','WORKSPACE PREFERENCES')+`<div class="content-grid"><section class="panel"><div class="panel-head"><h2>${esc(t('logo'))}</h2><span class="mono">.PNG</span></div><div class="panel-body"><div class="preview-logo">${prefs.logo?`<img src="${prefs.logo}" alt="${esc(t('logoAlt'))}">`:`<div class="brand">${brand()}</div>`}</div><label class="field" style="margin-top:24px">${esc(t('logoUpload'))}<input id="logo-file" type="file" accept=".png,image/png" aria-describedby="logo-help"><small id="logo-help">${esc(t('logoHint'))}</small></label><div style="margin-top:24px">${button('logoReset','reset-logo',false,!prefs.logo?'disabled':'')}</div></div></section><aside><section class="panel"><div class="panel-head"><h2>${esc(t('languageTitle'))}</h2></div><div class="panel-body"><div class="actions"><button class="button ${lang==='ko'?'primary':''}" data-lang="ko" lang="ko" aria-pressed="${lang==='ko'}">한국어</button><button class="button ${lang==='en'?'primary':''}" data-lang="en" lang="en" aria-pressed="${lang==='en'}">English</button></div><p class="panel-description">${esc(t('languageHint'))}</p></div></section>${note('localNote')}</aside></div>`;}
/* 04 — Local registration/edit dialogs. No remote writes or permission grants. */
function field(key,name,value='',type='text',required=false,full=false){return `<label class="field ${full?'full':''}">${esc(t(key))}${required?' *':''}${type==='textarea'?`<textarea name="${name}" ${required?'required':''} maxlength="4000">${esc(value)}</textarea>`:`<input name="${name}" value="${esc(value)}" type="${type}" ${required?'required':''} ${type==='text'?'maxlength="200"':''}>`}</label>`;}
function selectField(key,name,values,current){return `<label class="field">${esc(t(key))}<select name="${name}">${values.map(v=>`<option value="${v}" ${v===current?'selected':''}>${esc(t(v))}</option>`).join('')}</select></label>`;}
function visibility(checked){return `<label class="check-field full"><input type="checkbox" name="public" ${checked?'checked':''}>${esc(t('public'))}</label><p class="small muted full">${esc(t('publicHelp'))}</p>`;}
function openDialog(title,body,onSubmit){const d=$('#dialog');d.innerHTML=`<form><div class="dialog-header"><h2 id="dialog-title">${esc(title)}</h2><button type="button" class="icon-button" data-close aria-label="${esc(t('closeDialog'))}">${icon('close')}</button></div><div class="form-grid">${body}</div><p class="form-error" id="form-error" role="alert"></p><div class="dialog-footer"><button type="button" class="button" data-close>${esc(t('cancel'))}</button>${onSubmit?`<button class="button primary" type="submit">${esc(t('save'))}</button>`:''}</div></form>`;d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());$('form',d).onsubmit=async e=>{e.preventDefault();if(!onSubmit)return;const submit=$('button[type=submit]',d);submit.disabled=true;$('#form-error').textContent='';try{await onSubmit(new FormData(e.target));}catch(err){$('#form-error').textContent=t(err.message)||err.message;if(err.code==='version_conflict'){$('#form-error').insertAdjacentHTML('beforeend',`<br><button type="button" class="button" id="conflict-refresh">${esc(t('refresh'))}</button>`);$('#conflict-refresh').onclick=async()=>{try{await refreshState();$('#dialog').close();render();}catch(e){toast(e.message);}};}}finally{submit.disabled=false;}};d.showModal();}
function projectForm(edit=false){const p=edit?currentProject():{};openDialog(t(edit?'edit':'newProject'),companySelect(p.company)+field('title','title',p.title,'text',true,true)+field('site','site',p.site,'text',true,true)+field('start','start',p.start,'date',true)+field('end','end',p.end,'date',true)+selectField('status','status',['planned','active','completed'],p.status||'planned')+field('currentPhase','phase',p.phase)+visibility(p.public),async f=>{if(f.get('end')<f.get('start'))throw Error('invalidDate');const next=structuredClone(db);const record={...p,id:p.id||id(),company:f.get('company')||p.company,title:f.get('title').trim(),site:f.get('site').trim(),start:f.get('start'),end:f.get('end'),status:f.get('status'),phase:f.get('phase').trim(),public:f.has('public')};if(!record.title||!record.site)return;const idx=next.projects.findIndex(x=>x.id===record.id);if(idx<0)next.projects.unshift(record);else next.projects[idx]=record;log(next,edit?'changeEdited':'changeCreated',record,record.id);await saveDB(next);$('#dialog').close();navigate(href('overview',record.id,'','pm'));toast(t('saved'));});}
function fileInput(accept,multiple=false){return `<label class="field full">${esc(t('file'))} *<input type="file" name="file" accept="${accept}" ${multiple?'multiple':''} required><small>${esc(t('fileLimit'))}</small></label>`;}
function itemForm(edit=false){const uploadIds=new Map();const uploadProject=route.project;const type=route.tab;const old=edit?items(type).find(i=>i.id===route.item):{};const fileType=['designs','photos','estimates'].includes(type);let fields='';
 if(fileType&&!edit)fields+=fileInput(type==='designs'?'.skp,.pdf,.dwg':type==='estimates'?'.pdf':'image/png,image/jpeg',type==='photos');
 fields+=field('title','title',old.title,'text',!fileType||edit,true);
 if(type==='materials')fields+=field('category','category',old.category)+field('space','space',old.space)+field('spec','spec',old.spec,'textarea',false,true)+field('quantity','quantity',old.quantity)+field('unitPrice','price',old.price)+`<p class="small muted full">${esc(t('unitHint'))}</p>`;
 if(type==='materials')fields+=`<label class="field full">${esc(t('materialImage'))}<input type="file" name="materialImage" accept="image/png,image/jpeg"><small>${esc(t('fileLimit'))}</small></label>`;
 if(type==='schedule')fields+=field('startDate','date',old.date||today(),'date',true)+field('startTime','time',old.time||'','time')+field('endDate','endDate',old.endDate||'','date')+field('endTime','endTime',old.endTime||'','time')+`<p class="full small muted">${esc(t('seoulTime'))}</p>`;
 if(type==='photos')fields+=field('shotDate','date',old.date||today(),'date',true);
 if(type==='photos')fields+=field('phase','phase',old.phase,'text',true);
 if(type==='estimates')fields+=field('version','versionLabel',old.versionLabel)+`<p class="small muted full">${esc(t('versionHint'))}</p>`;
 if(type==='requests'&&edit){fields=field('title','title',old.title,'text',true,true)+selectField('status','status',['open','working','resolved'],old.status);}
 else if(type!=='materials')fields+=field(type==='requests'?'requestBody':'description','description',old.description,'textarea',type==='requests',true);
 if(route.role==='pm')fields+=visibility(old.public);
 openDialog(t(edit?'edit':'add')+' · '+t(type),fields,async f=>{const files=!edit&&fileType?f.getAll('file'):[];let entries=[];if(files.length){for(const [index,file] of files.entries()){const key=index+':'+file.name+':'+file.size+':'+file.lastModified;if(!uploadIds.has(key))uploadIds.set(key,id());const stableId=uploadIds.get(key);if(db.items.some(item=>item.id===stableId))continue;await validateFile(file,type);entries.push({id:stableId,fileName:file.name,data:await readData(file)});}}else entries=[{}];const next=structuredClone(db);
 const materialFile=f.get('materialImage');let materialImage=old.materialImage;if(type==='materials'&&materialFile?.size){await validateFile(materialFile,'photos');materialImage=await readData(materialFile);}
 for(const file of entries){const entry={...old,...file,id:old.id||file.id||id(),project:uploadProject,type,created:old.created||new Date().toISOString(),title:f.get('title').trim()||file.fileName,public:route.role==='pm'?f.has('public'):route.role==='customer'};for(const key of ['category','space','spec','quantity','price','date','phase','versionLabel','description','time','endDate','endTime'])if(f.has(key))entry[key]=f.get(key).trim();if(type==='materials'&&materialImage)entry.materialImage=materialImage;if(type==='requests')entry.status=f.get('status')||old.status||'open';const idx=next.items.findIndex(i=>i.id===entry.id);if(idx<0)next.items.unshift(entry);else next.items[idx]=entry;log(next,edit?'changeEdited':'changeCreated',entry,route.project);}
 if(type==='photos'&&files.length>1){await savePhotoBatch(next.items.filter(item=>[...uploadIds.values()].includes(item.id)&&!db.items.some(saved=>saved.id===item.id)),files.length);}else await saveDB(next);$('#dialog').close();render();toast(t('saved'));});
}
function requestForm(reply=false){const old=items('requests').find(i=>i.id===route.item);openDialog(t(reply?'reply':'correction'),reply?field('answer','text',old.answer,'textarea',true,true)+selectField('status','status',['open','working','resolved'],old.status):field('correction','text','','textarea',true,true),async f=>{const next=structuredClone(db),item=next.items.find(i=>i.id===old.id);if(reply){item.answer=f.get('text').trim();item.status=f.get('status');}else(item.corrections??=[]).push({text:f.get('text').trim(),at:new Date().toISOString()});log(next,'changeEdited',item,route.project);await saveDB(next);$('#dialog').close();render();toast(t('saved'));});}
function previewForm(){openDialog(t('addPreview'),field('previewLabel','title','','text',true,true)+fileInput('image/png,image/jpeg'),async f=>{const file=f.get('file');await validateFile(file,'photos');const next=structuredClone(db),item=next.items.find(i=>i.id===route.item);(item.previews??=[]).push({id:id(),title:f.get('title').trim(),data:await readData(file)});log(next,'changePreview',item,route.project);await saveDB(next);$('#dialog').close();render();toast(t('saved'));});}
function readData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('invalidImage'));r.readAsDataURL(file);});}
function decodeImage(data){return new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>i.naturalWidth&&i.naturalHeight?resolve(i):reject(Error('invalidImage'));i.onerror=()=>reject(Error('invalidImage'));i.src=data;});}
async function decodeComparisonImage(data){const url=safeImage(data);if(!url)throw Error('invalidImage');if(!url.startsWith('/api/files/'))return decodeImage(url);const response=await fetch(url,{credentials:'same-origin',cache:'no-store'});if([401,403,404].includes(response.status))throw Error('compareDenied');if(!response.ok)throw Error('invalidImage');const objectURL=URL.createObjectURL(await response.blob());try{return await decodeImage(objectURL);}finally{URL.revokeObjectURL(objectURL);}}
async function validateFile(file,type){if(!file||!file.size)throw Error(type==='photos'?'imageOnly':'drawingTypes');if(file.size>20*1024*1024)throw Error('tooLarge');if(type==='designs'&&!C.drawingAllowed(file.name))throw Error('drawingTypes');if(type==='estimates'&&!/\.pdf$/i.test(file.name))throw Error('pdfOnly');if(/\.pdf$/i.test(file.name)&&type!=='photos'){const sig=new TextDecoder().decode(await file.slice(0,5).arrayBuffer());if(sig!=='%PDF-')throw Error('invalidPdf');}if(type==='photos'){if(!/\.(png|jpe?g)$/i.test(file.name)||!['image/png','image/jpeg'].includes(file.type))throw Error('imageOnly');await decodeImage(await readData(file));}}
/* 05 — Bind actions after each route render; upload logo is local-only. */
function bind(){
 document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=async()=>{try{await savePrefs({...prefs,lang:b.dataset.lang});lang=C.language(prefs.lang);render();}catch(e){toast(e.message);}});
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});
 $('#search')?.addEventListener('input',e=>{query=e.target.value;const all=db.projects.filter(p=>!p.archived&&(route.role!=='customer'||p.public));$('#project-results').innerHTML=projectResults(all);$('#result-count').textContent=all.filter(p=>(filter==='all'||p.status===filter)&&(p.title+' '+p.site).toLowerCase().includes(query.toLowerCase())).length;bindActions($('#project-results'));});
 document.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+Number(b.dataset.month),1);render();});
 $('#logo-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const error=C.logoError(file.name,file.size,new Uint8Array(await file.slice(0,8).arrayBuffer()));if(error)throw Error(error);const data=(await readData(file)).replace(/^data:[^;]*;/,"data:image/png;");await decodeImage(data);if(await savePrefs({...prefs,logo:data})){render();toast(t('saved'));}}catch(err){toast(t(err.message));e.target.value='';}});
 bindActions(document);setupCompare();
}
function bindActions(root){root.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{
 const a=b.dataset.action;
 if(a==='help')openDialog(t('helpTitle'),`<p class="full">${esc(t('helpText'))}</p>`);
 else if(a==='new-project'&&route.role==='pm')projectForm();
 else if(a==='edit-project'&&route.role==='pm')projectForm(true);
 else if(a==='add-item'&&(route.role==='pm'||route.tab==='requests'||(route.role==='field'&&route.tab==='photos')))itemForm();
 else if(a==='edit-item'&&route.role==='pm')itemForm(true);
 else if(a==='correct-request')requestForm();
 else if(a==='reply-request'&&route.role==='pm')requestForm(true);
 else if(a==='add-preview'&&route.role==='pm')previewForm();
 else if(a==='reset-logo'&&await savePrefs({...prefs,logo:''})){render();toast(t('saved'));}
 });}
window.addEventListener('hashchange',()=>{filter='all';query='';workQuery='';workFacet='';workDate='';verifyRoute();});

