let workQuery='',workFacet='',workDate='';
db.clients??=[];
function snapshot(record){return Object.fromEntries(Object.entries(record).filter(([k])=>!['data','previews','materialImage'].includes(k)));}
function projectSwitcher(p){const all=db.projects.filter(x=>!x.archived&&(route.role!=='customer'||x.public));return `<label class="project-switch mono">${esc(t('switchProject'))}<select id="project-switch">${all.map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label>`;}
function clientsView(){
 const c=route.item?db.clients.find(x=>x.id===route.item):null;if(route.item&&!c)return unavailable();
 if(c)return heading(c.title,t('clientNote'),`<button class="button primary" id="edit-client">${esc(t('edit'))}${icon('arrow')}</button>`,'CLIENT / CONTACT')+`<div class="content-grid"><section class="panel"><div class="panel-head"><h2>${esc(t('detail'))}</h2></div><div class="panel-body">${details([['clientName',c.title],['contact',c.contact],['email',c.email]])}<p class="description panel-description">${esc(c.description)}</p></div></section><section class="panel"><div class="panel-head"><h2>${esc(t('related'))}</h2></div>${db.projects.filter(p=>(c.projects||[]).includes(p.id)).map(p=>`<a class="project-card" href="${href('overview',p.id,'','pm')}"><h3>${esc(p.title)}</h3><p class="muted small">${esc(p.site)}</p></a>`).join('')||`<div class="panel-body muted">${esc(t('empty'))}</div>`}</section></div><a class="text-link" href="#/pm/customers">${icon('left')}${esc(t('back'))}</a>`;
 return heading(t('customers'),t('clientNote'),`<button class="button primary" id="new-client">${esc(t('newClient'))}${icon('plus')}</button>`,'CLIENT DIRECTORY / 02')+`<div class="panel">${db.clients.length?db.clients.map(c=>`<a class="project-card" href="#/pm/customers/${esc(c.id)}"><div class="project-card-head"><h2>${esc(c.title)}</h2>${icon('arrow')}</div><p class="project-meta">${esc(c.contact)} · ${esc(c.email)}</p></a>`).join(''):empty('noClients','clientNote')}</div>`;
}
function clientForm(edit=false){const c=edit?db.clients.find(x=>x.id===route.item):{};openDialog(t(edit?'edit':'newClient'),companySelect(c.company)+field('clientName','title',c.title,'text',true,true)+field('contact','contact',c.contact,'tel')+field('email','email',c.email,'email')+field('description','description',c.description,'textarea',false,true)+`<div class="full"><span>${esc(t('related'))}</span>${db.projects.map(p=>`<label class="check-field"><input type="checkbox" name="projects" value="${esc(p.id)}" ${(c.projects||[]).includes(p.id)?'checked':''}>${esc(p.title)}</label>`).join('')}<p class="small muted">${esc(t('clientProjectHint'))}</p></div>`,async f=>{const title=f.get('title').trim();if(!title)return;const next=structuredClone(db),record={...c,id:c.id||id(),company:f.get('company')||c.company,type:'client',title,contact:f.get('contact').trim(),email:f.get('email').trim(),description:f.get('description').trim(),projects:f.getAll('projects').filter(id=>db.projects.some(p=>p.id===id))};const ix=next.clients.findIndex(x=>x.id===record.id);if(ix<0)next.clients.push(record);else next.clients[ix]=record;log(next,edit?'changeEdited':'changeCreated',record,null);await saveDB(next);$('#dialog').close();navigate('#/pm/customers/'+record.id);toast(t('saved'));});}
function historyView(){
 if(route.item){const h=db.history.find(x=>x.id===route.item);if(!h)return unavailable();const diff=value=>value?`<dl class="details">${Object.entries(value).filter(([k])=>!['id','project','type'].includes(k)).map(([k,v])=>`<dt>${esc(COPY[k]?t(k):k)}</dt><dd>${esc(typeof v==='object'?JSON.stringify(v):v)}</dd>`).join('')}</dl>`:`<p class="muted">${esc(h.after?t('empty'):t('noSnapshot'))}</p>`;const target=h.type==='client'?'#/pm/customers/'+h.idRef:href(h.type,h.project,h.type==='overview'?'':h.idRef,'pm');return heading(h.title,formatDate(h.at),'','CHANGE RECORD')+`<div class="content-grid equal"><section class="panel"><div class="panel-head"><h2>${esc(t('before'))}</h2></div><div class="panel-body">${diff(h.before)}</div></section><section class="panel"><div class="panel-head"><h2>${esc(t('after'))}</h2></div><div class="panel-body">${diff(h.after)}</div></section></div><div class="actions"><a class="text-link" href="#/pm/history">${icon('left')}${esc(t('back'))}</a><a class="text-link" href="${target}">${esc(t('originalRecord'))}${icon('arrow')}</a></div>`;}
 const list=db.history.filter(h=>(!workFacet||h.project===workFacet)&&h.title.toLowerCase().includes(workQuery.toLowerCase()));return heading(t('history'),t('localRecords'),'','CHANGELOG / 04')+workFilters(true)+`<div class="panel">${list.length?list.map(h=>`<a class="history-row" href="#/pm/history/${h.id}"><span class="mono">${esc(formatDate(h.at))}</span><strong>${esc(h.title)}</strong><span>${esc(t(h.key))}</span>${icon('arrow')}</a>`).join(''):empty('noUpdates','localRecords')}</div>`;
}
function overviewView(p){return `<section class="panel home-message"><div class="panel-head"><h2>${esc(t('home'))}</h2>${route.role==='pm'?`<div class="actions"><button class="button" id="preview-home">${esc(t('viewCustomer'))}</button><button class="button" id="edit-home">${esc(t('editHome'))}${icon('arrow')}</button></div>`:''}</div><div class="panel-body"><p class="description">${esc(p.homeMessage||t('overviewSub'))}</p></div></section>`+baseOverviewView(p);}
function homeForm(){const p=currentProject();openDialog(t('editHome'),field('homeMessage','homeMessage',p.homeMessage||'','textarea',true,true)+`<p class="full muted small">${esc(t('homeHelp'))}</p>`,async f=>{const next=structuredClone(db),item=next.projects.find(x=>x.id===p.id);item.homeMessage=f.get('homeMessage').trim();log(next,'changeEdited',item,p.id);await saveDB(next);$('#dialog').close();render();toast(t('saved'));});}
function workFilters(history=false){if(!history&&!['materials','photos','requests','estimates'].includes(route.tab))return '';const values=history?db.projects.map(p=>({value:p.id,label:p.title})):route.tab==='requests'?['open','working','resolved'].map(s=>({value:s,label:t(s)})):[...new Set(items(route.tab).map(i=>i[route.tab==='materials'?'category':route.tab==='photos'?'phase':'versionLabel']).filter(Boolean))].map(s=>({value:s,label:s}));return `<div class="work-filters ${route.tab==='photos'?'with-date':''}"><label class="field"><span class="sr-only">${esc(t('filterItems'))}</span><input type="search" id="work-search" placeholder="${esc(t('filterHint'))}" value="${esc(workQuery)}"></label><label class="field"><span class="sr-only">${esc(t(history?'project':route.tab==='materials'?'category':route.tab==='photos'?'phase':route.tab==='requests'?'status':'versionLabel'))}</span><select id="work-facet"><option value="">${esc(t('all'))}</option>${values.map(v=>`<option value="${esc(v.value)}" ${workFacet===v.value?'selected':''}>${esc(v.label)}</option>`).join('')}</select></label>${route.tab==='photos'?`<label class="field"><span class="sr-only">${esc(t('shotDate'))}</span><input id="work-date" type="date" value="${esc(workDate)}" aria-label="${esc(t('shotDate'))}"></label>`:''}</div>`;}
function filteredItems(list){return list.filter(i=>(!workDate||i.date===workDate)&&(!workFacet||i[route.tab==='materials'?'category':route.tab==='photos'?'phase':route.tab==='requests'?'status':'versionLabel']===workFacet)&&[i.title,i.description,i.space,i.phase,i.spec].filter(Boolean).join(' ').toLowerCase().includes(workQuery.toLowerCase()));}
function detailView(item){let html=baseDetailView(item);if(item.type==='estimates'){const list=items('estimates').filter(x=>(x.series||x.id)===(item.series||item.id));html+=`<section class="panel"><div class="panel-head"><h2>${esc(t('versions'))}</h2>${route.role==='pm'?`<button class="button primary" id="new-version">${esc(t('newVersion'))}${icon('plus')}</button>`:''}</div><div class="panel-body">${list.map(v=>`<a class="timeline-row" href="${href('estimates',v.project,v.id)}"><span>${esc(v.versionLabel||'—')}</span><span>${esc(v.title)} · ${esc(formatDate(v.created))}</span></a>`).join('')}</div></section>`;}return html;}
function versionForm(){const old=items('estimates').find(x=>x.id===route.item);openDialog(t('newVersion'),`<p class="full muted">${esc(t('versionNote'))}</p>`+fileInput('.pdf')+field('title','title',old.title,'text',true,true)+field('version','versionLabel','','text',true)+field('description','description','','textarea',true,true)+visibility(false),async f=>{const file=f.get('file');await validateFile(file,'estimates');const next=structuredClone(db),item={id:id(),project:old.project,type:'estimates',series:old.series||old.id,title:f.get('title').trim(),versionLabel:f.get('versionLabel').trim(),description:f.get('description').trim(),created:new Date().toISOString(),public:f.has('public'),fileName:file.name,data:await readData(file)};if(!item.title||!item.versionLabel||!item.description)return;next.items.unshift(item);log(next,'changeCreated',item,item.project);await saveDB(next);$('#dialog').close();navigate(href('estimates',item.project,item.id));toast(t('saved'));});}
function architecturalDrawing(){return `<div class="architecture" aria-hidden="true"><span class="drawing-label mono">SPATIAL WORKFLOW — 01 / 06</span><svg viewBox="0 0 680 280" fill="none"><g class="draft-grid" stroke="currentColor" stroke-width=".5" opacity=".24"><path d="M0 220H680M0 160H680M0 100H680M100 0V280M220 0V280M340 0V280M460 0V280M580 0V280"/></g><g class="draft-lines" stroke="currentColor" stroke-width="1.3"><path d="M130 195 330 265 567 145 365 76Z M130 195V94L365 4 567 45V145 M130 94 330 163 567 45 M330 163V265 M365 4V76 M220 126V226 M220 177 365 110 450 140 M450 140V206 M365 110V76 M420 84V169 M470 60V130 M260 239 495 119 M270 110V146 M155 205V113 M175 119V212"/><path d="M145 98 333 155 546 46 M136 185 327 252 553 140 M237 157 327 189 404 151 314 122Z M237 157V175L327 207 404 169V151 M327 189V207"/></g><g stroke="#fa3600" stroke-width="2" class="accent-lines"><path d="M130 70V48H152 M546 173H568V151 M319 244V222H341 M125 194h20m-10-10v20 M357 76h20m-10-10v20"/></g><g font-family="monospace" font-size="8" fill="currentColor"><text x="140" y="37">PLAN / DRAW / BUILD</text><text x="460" y="245">CONNECTED WORKSPACE</text></g></svg><span class="drawing-caption mono">[ DESIGN → MATERIAL → SITE ]</span></div>`;}
function enhance(){
 $('#skip').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});};
 $('#new-client')?.addEventListener('click',()=>clientForm());$('#edit-client')?.addEventListener('click',()=>clientForm(true));$('#edit-home')?.addEventListener('click',homeForm);$('#new-version')?.addEventListener('click',versionForm);
 $('#project-switch')?.addEventListener('change',e=>navigate(href(route.tab,e.target.value)));
 $('#work-date')?.addEventListener('change',e=>{workDate=e.target.value;render();});
 $('#work-facet')?.addEventListener('change',e=>{workFacet=e.target.value;render();});
 $('#work-search')?.addEventListener('input',e=>{const at=e.target.selectionStart;workQuery=e.target.value;render();$('#work-search')?.focus();try{$('#work-search')?.setSelectionRange(at,at);}catch{}});
 if(route?.page==='preferences'){$('.workspace')?.insertAdjacentHTML('beforeend',`<section class="panel backup-panel"><div class="panel-head"><h2>${esc(t('downloadBackup'))}</h2><button class="button" id="export-data">${esc(t('download'))}${icon('arrow')}</button></div><div class="panel-body small muted">${esc(t('backupHelp'))}</div></section>`);$('#export-data').onclick=()=>{location.href='/api/export';};}
 window.dispatchEvent(new Event('workspace-render'));
}


